            String name = attr.getLocalName();
            if (name == null) {
                continue;
            }
            if (ATTR_FILL_TYPE.equals(name)) {
                report(context, attr, "The `fillType` attribute is not supported for generated "
                        + "raster images");
            } else if (ATTR_STROKE_DASH_ARRAY.equals(name)
