        }
    }

    private static int getDimension(Element element, String attributeName) {
        String value = element.getAttributeNS(ANDROID_URI, attributeName);
        if (value == null || value.isEmpty()) {
            return 0;
        }
        if (value.endsWith("dp")) {
            try {
                return Integer.parseInt(value.substring(0, value.length() - 2));
            } catch (NumberFormatException e) {
                return 0;
            }
        } else if (value.endsWith("dip")) {
            try {
                return Integer.parseInt(value.substring(0, value.length() - 3));
            } catch (NumberFormatException e) {
                return 0;
            }
        }
        return 0;
    }

    private static void report(XmlContext context, Node node, String message) {
        context.report(ISSUE, node, context.getLocation(node), message, null);
